//-----------------------------------------------------------------------------
// PluginManager
//
// The static class that manages the plugins.

function PluginManager() {
    throw new Error('This is a static class');
}

PluginManager._path         = 'js/plugins/';
PluginManager._scripts      = [];
PluginManager._errorUrls    = [];
PluginManager._parameters   = {};

PluginManager.setup = function(plugins) {
    var self = this;
    // Dynamic script elements are not guaranteed to have executed when the
    // next line of main.js runs. Load the enabled plugins in project order and
    // resolve only after each script has actually executed, so plugin hooks
    // (notably Omori Name Input's input initializer) exist before SceneManager
    // starts its first frame.
    return plugins.reduce(function(chain, plugin) {
        if (!plugin.status || self._scripts.contains(plugin.name)) {
            return chain;
        }
        return chain.then(function() {
            self.setParameters(plugin.name, plugin.parameters);
            return self.loadScript(plugin.name + '.js').then(function() {
                self._scripts.push(plugin.name);
            });
        });
    }, Promise.resolve());
};

PluginManager.loadScript = function(name) {
    var url = this._path + name;
    // Mods overlay js/plugins/* into the browser VFS. When a plugin is present
    // there (a modded or mod-patched plugin), execute it from a Blob URL with
    // the same global scope and ordered-by-promise semantics as on-disk
    // plugins, without a network request.
    var vfsText = null;
    if (typeof ZipLoader !== 'undefined' && ZipLoader.getText) {
        vfsText = ZipLoader.getText(url);
    }
    if (vfsText != null) {
        return this._loadScriptFromBlob(name, url, vfsText);
    }
    var script = document.createElement('script');
    script.type = 'text/javascript';
    script.src = url;
    script.async = false;
    script._url = url;
    return new Promise(function(resolve, reject) {
        script.onload = function() {
            resolve(script);
        };
        script.onerror = function(event) {
            PluginManager.onError(event);
            reject(new Error('Failed to load: ' + url));
        };
        document.body.appendChild(script);
    });
};

PluginManager._loadScriptFromBlob = function(name, url, code) {
    var blob = new Blob([code], { type: 'text/javascript' });
    var blobUrl = URL.createObjectURL(blob);
    var script = document.createElement('script');
    script.type = 'text/javascript';
    script.src = blobUrl;
    script.async = false;
    script._url = url;
    return new Promise(function(resolve, reject) {
        script.onload = function() {
            URL.revokeObjectURL(blobUrl);
            resolve(script);
        };
        script.onerror = function(event) {
            URL.revokeObjectURL(blobUrl);
            PluginManager.onError(event);
            reject(new Error('Failed to load: ' + url));
        };
        document.body.appendChild(script);
    });
};

PluginManager.checkErrors = function() {
    var url = this._errorUrls.shift();
    if (url) {
        throw new Error('Failed to load: ' + url);
    }
};

PluginManager.parameters = function(name) {
    return this._parameters[name.toLowerCase()] || {};
};

PluginManager.setParameters = function(name, parameters) {
    this._parameters[name.toLowerCase()] = parameters;
};

PluginManager.onError = function(e) {
    this._errorUrls.push(e.target._url);
};

